// ловим ролики на взлёте: свежие + макс views/час
const s = $('Seeds').first().json;
const maxAgeH = Number(s.max_age_hours || 72);
const minViews = Number(s.min_views || 20000);
const topN = Number(s.top_n || 10);
const raw = items.flatMap(i => Array.isArray(i.json) ? i.json : (i.json.items || [i.json]));
const now = Date.now();
const scored = raw.map(v => {
  const views = v.playCount ?? v.videoViewCount ?? v.views ?? 0;
  const likes = v.diggCount ?? v.likesCount ?? v.likes ?? 0;
  const shares = v.shareCount ?? v.shares ?? 0;
  const comments = v.commentCount ?? v.comments ?? 0;
  const saves = v.collectCount ?? v.saves ?? 0;
  const created = v.createTimeISO ? new Date(v.createTimeISO).getTime() : (v.createTime ? v.createTime*1000 : now);
  const ageH = Math.max(1, (now - created)/3600000);
  const vph = Math.round(views / ageH);                      // СКОРОСТЬ набора просмотров
  const eng = views ? Math.round(((shares*3+saves*2+comments*1.5+likes)/views)*1000)/10 : 0; // алгоритм-сигнал
  return { src_url: v.webVideoUrl||v.url||v.videoUrl||'', src_platform: 'tiktok',
    src_views: views, src_likes: likes, src_caption: (v.text||v.caption||'').slice(0,500),
    age_hours: Math.round(ageH), views_per_hour: vph, eng_rate: eng };
});
const kept = scored
  .filter(v => v.src_url && v.age_hours <= maxAgeH && v.src_views >= minViews)
  .sort((a,b) => b.views_per_hour - a.views_per_hour)
  .slice(0, topN);
return kept.map(json => ({ json }));

